"""Controllo delle regole di formato della dispensa Obsidian (uso: python -I check_dispensa.py file1.md [file2.md ...])."""
import re
import sys
from pathlib import Path

FILE_AMMESSI = {
    "00 - Indice Generale ITS (MOC)", "00 - Indice AWS (MOC)", "01 - Fondamenti di networking",
    "02 - Reti Wi-Fi e VPN", "03 - Simulazione dei protocolli di rete", "04 - Fondamenti di cloud computing",
    "05 - Classificazione dei servizi cloud", "06 - Immagini, container e registri",
    "07 - Dockerfile, networking e Kubernetes", "99 - Glossario, Comandi e Cheat Sheet AWS",
}
CALLOUT_AMMESSI = {"abstract", "important", "example", "warning", "success"}
LINGUAGGI = {"powershell", "bash", "dockerfile", "yaml", "python", "json", "http", "text", "mermaid"}


def titoli_di(percorso):
    """Restituisce l'insieme dei testi dei titoli H1-H6 di un file (fuori dai blocchi di codice)."""
    titoli = set()
    in_codice = False
    for riga in Path(percorso).read_text(encoding="utf-8").splitlines():
        nuda = re.sub(r"^(> ?)+", "", riga)
        if nuda.startswith("```"):
            in_codice = not in_codice
            continue
        if not in_codice:
            m = re.match(r"^(#{1,6}) (.+)$", riga)
            if m:
                titoli.add(m.group(2).strip())
    return titoli


def controlla(percorso, tutti_i_titoli):
    """Stampa le violazioni trovate nel file indicato."""
    testo = Path(percorso).read_text(encoding="utf-8")
    righe = testo.splitlines()
    problemi = []
    in_codice = False
    apertura = None
    for n, riga in enumerate(righe, 1):
        in_callout = riga.startswith(">")
        nuda = re.sub(r"^(> ?)+", "", riga) if in_callout else riga
        if nuda.startswith("```"):
            if not in_codice:
                lingua = nuda[3:].strip()
                if lingua not in LINGUAGGI:
                    problemi.append(f"{n}: blocco di codice senza linguaggio ammesso: '{lingua}'")
                in_codice = True
                apertura = (n, in_callout)
            else:
                if apertura and apertura[1] != in_callout:
                    problemi.append(f"{n}: chiusura del blocco con prefisso '>' diverso dall'apertura (riga {apertura[0]})")
                in_codice = False
            continue
        if in_codice:
            if apertura and apertura[1] and not in_callout:
                problemi.append(f"{n}: riga di codice dentro un callout senza prefisso '> '")
            continue
        m = re.match(r"^(#{1,6}) (.+)$", riga)
        if m:
            if re.search(r"[#\^\[\]\|:]", m.group(2)):
                problemi.append(f"{n}: titolo con carattere vietato: {m.group(2)}")
        mc = re.match(r"^> \[!([a-z]+)\]([-+]?)(.*)$", riga)
        if mc:
            tipo, piega, titolo = mc.groups()
            if tipo not in CALLOUT_AMMESSI:
                problemi.append(f"{n}: callout non ammesso: {tipo}")
            if not titolo.strip():
                problemi.append(f"{n}: callout senza titolo")
            if tipo == "success" and (piega != "-" or titolo.strip() != "Risposte"):
                problemi.append(f"{n}: callout success non nel formato '> [!success]- Risposte'")
        # segnaposto <...> fuori dal codice inline
        senza_inline = re.sub(r"`[^`]*`", "", nuda)
        for seg in re.findall(r"<[^>\s][^>]*>", senza_inline):
            problemi.append(f"{n}: possibile tag/segnaposto fuori dai backtick: {seg}")
        # wikilink
        for link in re.findall(r"\[\[([^\]]+)\]\]", riga):
            destinazione = re.split(r"\\?\|", link)[0]
            file_link, _, ancora = destinazione.partition("#")
            if file_link not in FILE_AMMESSI:
                problemi.append(f"{n}: wikilink verso file non ammesso: {file_link}")
            elif ancora:
                titoli = tutti_i_titoli.get(file_link)
                if titoli is None:
                    problemi.append(f"{n}: ancora verso un file di altro autore: {destinazione}")
                elif ancora not in titoli:
                    problemi.append(f"{n}: ancora inesistente: {destinazione}")
            if "|" in link and not "\\|" in link and riga.lstrip("> ").startswith("|"):
                problemi.append(f"{n}: alias di wikilink non protetto in tabella: {link}")
    if in_codice:
        problemi.append("blocco di codice non chiuso a fine file")
    parole = len(re.findall(r"\w+", testo))
    print(f"== {percorso}\n   parole stimate: {parole}")
    for p in problemi:
        print("   " + p)
    if not problemi:
        print("   nessun problema rilevato")


if __name__ == "__main__":
    file_md = sys.argv[1:]
    tutti = {}
    for f in file_md:
        tutti[Path(f).stem] = titoli_di(f)
    for f in file_md:
        controlla(f, tutti)

